parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "id": { "type": "number" },
    "valid": { "type": "boolean" },
    "invalid_reason": { "type": ["string", "null"] },
    "lemma": { "type": ["string", "null"] },
    "pos": { "type": ["string", "null"], "enum": ["noun","verb","adj","adv","prep","conj","pron","det","num","intj","article","particle",null] },
    "gender": { "type": ["string", "null"], "enum": ["m","f","m/f",null] },
    "ipa": { "type": ["string", "null"] },
    "level": { "type": ["string", "null"], "enum": ["A1","A2","B1","B2","C1","C2",null] },
    "topic": { "type": ["string", "null"], "enum": ["Basics","Nature","People & Society","Other","Descriptions","Body & Health","Communication","Money & Shopping","Actions","Places & Travel","Events","Home & Objects","Mind & Ideas","Life & Situations","Numbers & Quantity","Feelings","Food & Drink","Time","Animals","Sports & Games",null] },
    "en_1": { "type": ["string", "null"] },
    "en_2": { "type": ["string", "null"] },
    "en_3": { "type": ["string", "null"] },
    "with_article": { "type": ["string", "null"] },
    "plural": { "type": ["string", "null"] },
    "adj_forms": {
      "type": ["object", "null"],
      "properties": {
        "m_sg": { "type": "string" },
        "f_sg": { "type": "string" },
        "m_pl": { "type": "string" },
        "f_pl": { "type": "string" }
      },
      "required": ["m_sg","f_sg","m_pl","f_pl"]
    },
    "verb": {
      "type": ["object", "null"],
      "properties": {
        "auxiliary": { "type": "string", "enum": ["avere","essere"] },
        "present": { "type": "string" },
        "past": { "type": "string" },
        "future": { "type": "string" }
      },
      "required": ["auxiliary","present","past","future"]
    },
    "examples": {
      "type": "array",
      "maxItems": 3,
      "items": {
        "type": "object",
        "properties": {
          "level": { "type": "string", "enum": ["A2","B1","C1"] },
          "it": { "type": "string" },
          "en": { "type": "string" }
        },
        "required": ["level","it","en"]
      }
    }
  },
  "required": ["id","valid","invalid_reason","lemma","pos","gender","ipa","level","topic","en_1","en_2","en_3","with_article","plural","adj_forms","verb","examples"]
}

parameters.jsCode:
const input = $('Extract from File').item.json;
const r = { ...($json.output ?? $json), id: Number(input.id), original: input.word };

const errs = [];
if (r.valid) {
  if (!r.lemma || !/^[a-zà-ùA-ZÀ-Ù' ]+$/.test(r.lemma)) errs.push('bad lemma');
  if (!r.en_1) errs.push('no en_1');
  if (r.en_1 && r.en_1.toLowerCase() === (r.lemma || '').toLowerCase()) errs.push('en = it');
  if (!r.ipa) errs.push('no ipa');
  if (!Array.isArray(r.examples) || r.examples.length !== 3) errs.push('examples != 3');
  if (r.pos === 'noun' && (!r.with_article || !r.gender || !r.plural)) errs.push('noun fields missing');
  if (r.pos === 'verb' && !r.verb) errs.push('verb fields missing');
  if (r.pos === 'adj' && !r.adj_forms) errs.push('adj fields missing');
}
return { ...r, _errors: errs.join('; ') || null };

const groups = {};
const out = [];
for (const { json: r } of $input.all()) {
  if (!r.valid) { out.push(r); continue; }
  const key = `${r.lemma.toLowerCase()}|${r.pos}`;
  (groups[key] ??= []).push(r);
}
for (const list of Object.values(groups)) {
  list.sort((a, b) =>
    (b.original?.toLowerCase() === b.lemma.toLowerCase()) - (a.original?.toLowerCase() === a.lemma.toLowerCase())
    || a.id - b.id);
  const [main, ...rest] = list;
  out.push({ ...main, merged_ids: rest.map(r => r.id) });
  for (const r of rest) out.push({ id: r.id, valid: false, invalid_reason: `merged into ${main.id}`, merged_into: main.id });
}
return out.map(json => ({ json }));
